import pytest

from sqllineage.utils.entities import ColumnQualifierTuple

from ...helpers import assert_column_lineage_equal

# https://learn.microsoft.com/en-us/sql/t-sql/queries/from-transact-sql
# https://www.postgresql.org/docs/current/queries-table-expressions.html#QUERIES-LATERAL
# https://duckdb.org/docs/stable/sql/query_syntax/from#lateral-joins
# a VALUES list in FROM clause can refer to the datasets before it, with tsql CROSS APPLY / OUTER APPLY, or LATERAL.
# each column of the column alias list is generated by the values at the same position of every row.
_lateral_dialects = ["duckdb", "postgres"]


@pytest.mark.parametrize("dialect", ["tsql"])
def test_select_column_from_cross_apply_values(dialect: str):
    sql = """INSERT INTO tab1 (id, col1, col2)
SELECT s.id, v.col1, v.col2
FROM tab2 s
CROSS APPLY (VALUES (s.col3, s.col4), (s.col5, s.col6)) v (col1, col2)"""
    assert_column_lineage_equal(
        sql,
        [
            (
                ColumnQualifierTuple("id", "tab2"),
                ColumnQualifierTuple("id", "tab1"),
            ),
            (
                ColumnQualifierTuple("col3", "tab2"),
                ColumnQualifierTuple("col1", "tab1"),
            ),
            (
                ColumnQualifierTuple("col5", "tab2"),
                ColumnQualifierTuple("col1", "tab1"),
            ),
            (
                ColumnQualifierTuple("col4", "tab2"),
                ColumnQualifierTuple("col2", "tab1"),
            ),
            (
                ColumnQualifierTuple("col6", "tab2"),
                ColumnQualifierTuple("col2", "tab1"),
            ),
        ],
        dialect=dialect,
        test_sqlparse=False,
    )


@pytest.mark.parametrize("dialect", ["tsql"])
def test_select_unqualified_column_from_outer_apply_values(dialect: str):
    sql = """INSERT INTO tab1
SELECT id, item
FROM tab2
OUTER APPLY (VALUES (col1), (col2), ('constant')) AS v (item)"""
    assert_column_lineage_equal(
        sql,
        [
            (
                ColumnQualifierTuple("id", "tab2"),
                ColumnQualifierTuple("id", "tab1"),
            ),
            (
                ColumnQualifierTuple("col1", "tab2"),
                ColumnQualifierTuple("item", "tab1"),
            ),
            (
                ColumnQualifierTuple("col2", "tab2"),
                ColumnQualifierTuple("item", "tab1"),
            ),
        ],
        dialect=dialect,
        test_sqlparse=False,
    )


@pytest.mark.parametrize("dialect", ["tsql"])
def test_select_column_from_cross_apply_values_with_expression(dialect: str):
    sql = """INSERT INTO tab1
SELECT s.id, v.item
FROM tab2 s
CROSS APPLY (VALUES (s.col1 + s.col2), (UPPER(s.col3))) v (item)"""
    assert_column_lineage_equal(
        sql,
        [
            (
                ColumnQualifierTuple("id", "tab2"),
                ColumnQualifierTuple("id", "tab1"),
            ),
            (
                ColumnQualifierTuple("col1", "tab2"),
                ColumnQualifierTuple("item", "tab1"),
            ),
            (
                ColumnQualifierTuple("col2", "tab2"),
                ColumnQualifierTuple("item", "tab1"),
            ),
            (
                ColumnQualifierTuple("col3", "tab2"),
                ColumnQualifierTuple("item", "tab1"),
            ),
        ],
        dialect=dialect,
        test_sqlparse=False,
    )


@pytest.mark.parametrize("dialect", _lateral_dialects)
def test_select_column_from_lateral_values(dialect: str):
    sql = """INSERT INTO tab1
SELECT s.id, v.col1, v.col2
FROM tab2 s
CROSS JOIN LATERAL (VALUES (s.col3, s.col4), (s.col5, s.col6)) AS v (col1, col2)"""
    assert_column_lineage_equal(
        sql,
        [
            (
                ColumnQualifierTuple("id", "tab2"),
                ColumnQualifierTuple("id", "tab1"),
            ),
            (
                ColumnQualifierTuple("col3", "tab2"),
                ColumnQualifierTuple("col1", "tab1"),
            ),
            (
                ColumnQualifierTuple("col5", "tab2"),
                ColumnQualifierTuple("col1", "tab1"),
            ),
            (
                ColumnQualifierTuple("col4", "tab2"),
                ColumnQualifierTuple("col2", "tab1"),
            ),
            (
                ColumnQualifierTuple("col6", "tab2"),
                ColumnQualifierTuple("col2", "tab1"),
            ),
        ],
        dialect=dialect,
        test_sqlparse=False,
    )


@pytest.mark.parametrize("dialect", _lateral_dialects)
def test_select_wildcard_from_lateral_values(dialect: str):
    sql = """INSERT INTO tab1
SELECT s.id, v.*
FROM tab2 s, LATERAL (VALUES (s.col3, s.col4)) AS v (col1, col2)"""
    assert_column_lineage_equal(
        sql,
        [
            (
                ColumnQualifierTuple("id", "tab2"),
                ColumnQualifierTuple("id", "tab1"),
            ),
            (
                ColumnQualifierTuple("col3", "tab2"),
                ColumnQualifierTuple("col1", "tab1"),
            ),
            (
                ColumnQualifierTuple("col4", "tab2"),
                ColumnQualifierTuple("col2", "tab1"),
            ),
        ],
        dialect=dialect,
        test_sqlparse=False,
    )
